import { ScrollView, View } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { HeaderBar, SettingsItem } from '@/components'
import { router } from 'expo-router'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { humanizeCredits } from './utils/format'
import { useCurrentOrganization } from '@/utils/hooks'
import {
	purchaseCreditsEmitter,
	PurchaseCreditsEvents,
	upgradePlanEmitter,
	UpgradePlanEvents
} from '@/utils/emitter'

export const SubscriptionAndCreditsScreen = () => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()

	const { currentOrganization } = useCurrentOrganization()

	if (!currentOrganization) {
		return null
	}

	const onClose = () => {
		router.back()
	}

	const handleCurrentPlan = () => {
		upgradePlanEmitter.emit(UpgradePlanEvents.OPEN_MODAL)
	}

	const handlePurchaseCredits = () => {
		purchaseCreditsEmitter.emit(PurchaseCreditsEvents.OPEN_MODAL)
	}

	return (
		<ScrollView
			style={styles.scrollView(theme)}
			showsVerticalScrollIndicator={false}
			contentContainerStyle={{
				paddingTop: insets.top,
				paddingBottom: insets.bottom + 16,
				gap: 32
			}}
		>
			<HeaderBar
				title="Subscription & credits"
				onClose={onClose}
				showBackButton
			/>

			<View style={styles.section}>
				<SettingsItem
					title="Upgrade plan"
					onPress={handleCurrentPlan}
					type="button"
					appearance="primary"
				/>

				<SettingsItem
					title="Purchase credits"
					subtitle={`${humanizeCredits(
						currentOrganization.creditBalance
					)} credits${
						BigInt(currentOrganization.creditBalance) > 0n ? ' left' : ''
					}`}
					onPress={handlePurchaseCredits}
					type="button"
					appearance="primary"
				/>
			</View>
		</ScrollView>
	)
}

const styles = defineStyles({
	scrollView: (theme: Theme) => ({
		backgroundColor: colors[theme].background,
		paddingHorizontal: 24
	}),
	section: {
		gap: 28
	}
})
